begin;

update public.spell_catalog s set
  name_ru=v.name_ru,
  effect_summary=v.effect_summary,
  author_description=v.author_description,
  author_comment=v.author_comment,
  upcast=v.upcast,
  notes=v.notes,
  casting_time=coalesce(v.casting_time,s.casting_time)
from (values
('absorb-elements','Поглощение стихий','Реакцией, когда получаешь урон кислотой, холодом, огнём, электричеством или звуком, получаешь сопротивление этому типу урона до начала своего следующего хода, включая спровоцировавший урон. Первая рукопашная атака, которой ты попадёшь в следующем ходу, дополнительно наносит 1к6 урона того же типа.','Ты буквально ловишь часть стихии на себя, переживаешь удар лучше, а затем возвращаешь кусочек обратно первым подходящим ударом. Очень практичная магическая месть.','Сначала пережить взрыв, потом объяснить его владельцу принцип возврата товара.','Дополнительный урон следующей рукопашной атаки увеличивается на 1к6 за каждый уровень ячейки выше 1.','Сопротивление применяется и к урону, который вызвал реакцию. Дополнительный урон действует только на первую подходящую рукопашную атаку до конца следующего хода.','1 реакция, когда получаешь урон кислотой, холодом, огнём, электричеством или звуком'),
('beast-bond','Звериная связь','Касаешься дружелюбного или очарованного зверя с Интеллектом 3 или ниже и создаёшь телепатическую связь до 10 минут при концентрации. Пока вы видите друг друга, зверь понимает твои телепатические сообщения, может передавать простые эмоции и понятия и получает преимущество на атаки по существам в 5 футах от тебя, которых ты видишь.','Не полноценный разговор с животным, а очень удобный канал «туда опасно», «сюда» и «куси вот этого». Для боевого спутника — почти гарнитура связи.','Когда волк наконец понимает план лучше половины группы — это уже командная работа.','Не усиливается при использовании ячейки более высокого уровня.','Заклинание не срабатывает на зверя с Интеллектом 4 или выше. Связь работает только пока вы находитесь в пределах видимости друг друга.',null),
('catapult','Катапульта','Выбираешь незакреплённый предмет весом от 1 до 5 фунтов в пределах дистанции и запускаешь его по прямой на расстояние до 90 футов. Первое существо на пути совершает спасбросок Ловкости; при провале оно и предмет получают по 3к8 дробящего урона, а при успехе предмет продолжает полёт.','Любой подходящий предмет внезапно получает карьеру артиллерийского снаряда. Бутылка, кирпич, статуэтка — магия не осуждает выбор боеприпаса.','Если в комнате есть табуретка, у волшебника уже есть план.','За каждый уровень ячейки выше 1 максимальный вес предмета увеличивается на 5 фунтов, а урон — на 1к8.','Нельзя выбирать предмет, который кто-то носит или держит. При столкновении после проваленного спасброска урон получает и цель, и сам предмет.',null),
('cause-fear','Вызов страха','Одно видимое существо в пределах 60 футов совершает спасбросок Мудрости. При провале оно испугано тобой до конца заклинания; в конце каждого своего хода повторяет спасбросок, прекращая эффект при успехе. Конструкты и Нежить невосприимчивы.','Ты не создаёшь чудовище или иллюзию — просто заставляешь цель очень ясно осознать собственную смертность и связать это ощущение именно с тобой.','Иногда лучший спецэффект — это внезапно появившийся здравый страх.','Ячейкой 2 уровня или выше можно выбрать ещё одну цель за каждый уровень выше 1; выбранные существа должны находиться не далее 30 футов друг от друга.','Требуется концентрация. Конструкты и Нежить автоматически не подвергаются этому эффекту.',null),
('ceremony','Церемония','Проводишь один из священных обрядов: возвращение раскаявшегося существа к прежнему мировоззрению, создание святой воды, совершеннолетие (+1к4 к проверкам характеристик на 24 часа), посвящение вере (+1к4 к спасброскам на 24 часа), погребальный обряд, мешающий трупу стать Нежитью 7 дней, или свадьбу, дающую супругам +2 КД рядом друг с другом на 7 дней.','Час официальной религиозной магии на все случаи жизни: от свадьбы до похорон и от посвящения до изготовления святой воды. Жрец здесь одновременно священнослужитель, нотариус и отдел магических услуг.','Редкое заклинание, где главный боевой ресурс — правильно оформленный брак.','Не усиливается при использовании ячейки более высокого уровня.','Ритуал. Большинство обрядов требуют добровольных целей. Для свадьбы бонус действует, пока супруги в пределах 30 футов друг от друга; повторно получить его можно только после овдовения. Материальный компонент — серебряный порошок стоимостью 25 зм, расходуемый.',null),
('chaos-bolt','Стрела хаоса','Совершишь дальнобойную атаку заклинанием. При попадании цель получает 2к8 + 1к6 урона; тип определяется значением одного из выпавших к8: кислота, холод, огонь, силовое поле, электричество, яд, психический урон или звук. Если на двух к8 выпали одинаковые значения, энергия прыгает на другую цель в пределах 30 футов и совершается новая атака.','Заклинание, которое само не до конца знает, чем именно собирается убивать. Иногда оно ещё и решает, что одной цели мало, и продолжает путешествие.','Хаос — это когда даже урон узнаёт свой тип уже после броска кубиков.','За каждый уровень ячейки выше 1 добавляется 1к6 урона.','Каждая цель может быть поражена этим сотворением только один раз. При прыжке заново совершается атака и бросаются кости урона.',null),
('distort-value','Искажение ценности','Касаешься предмета размером не более 1 фута по каждой стороне и на 8 часов заставляешь его выглядеть примерно вдвое более или менее ценным: роскошнее, качественнее, хуже или дешевле. Осматривающий предмет может распознать иллюзию успешной проверкой Расследования против Сл твоих заклинаний.','Магия для переговоров с очень сомнительной деловой этикой. Можно сделать дешёвую безделушку похожей на дорогую или превратить сокровище в предмет, который никто не захочет красть.','Иллюзия не меняет цену предмета. Она меняет только уверенность покупателя.','Ячейкой 2 уровня или выше максимальный размер предмета увеличивается на 1 фут по каждой стороне за каждый уровень ячейки выше 1.','Заклинание изменяет только воспринимаемую ценность и внешний вид, а не реальные свойства предмета.',null),
('earth-tremor','Дрожь земли','Вызываешь толчок земли вокруг себя. Каждое существо кроме тебя в пределах 10 футов совершает спасбросок Ловкости; при провале получает 1к6 дробящего урона и падает ничком. Если поверхность — рыхлая земля или камень, она становится труднопроходимой до расчистки.','Небольшое персональное землетрясение: окружающие падают, пол портится, а ты остаёшься в центре с максимально невиновным видом.','Если враги хотели окружить мага, земля может выразить своё несогласие.','Урон увеличивается на 1к6 за каждый уровень ячейки выше 1.','Каждый участок труднопроходимой местности размером 5 футов можно расчистить вручную примерно за 1 минуту.',null),
('frost-fingers','Морозные пальцы','Из вытянутых пальцев вырывается ледяной холод 15-футовым конусом. Существа в области совершают спасбросок Телосложения, получая 2к8 урона холодом при провале или половину при успехе. Незащищённые немагические жидкости в области замерзают.','Почти огненные ладони, только климатически противоположные и значительно лучше подходят для того, чтобы испортить кому-нибудь напиток.','Когда волшебник показывает пальцем и в комнате внезапно наступает зима.','Урон увеличивается на 1к8 за каждый уровень ячейки выше 1.','Немагические жидкости замерзают, если их никто не носит и не держит.',null),
('gift-of-alacrity','Дар проворства','Касаешься добровольного существа. В течение 8 часов оно добавляет 1к8 к своим броскам инициативы.','Очень простая хрономагия: цель начинает бой как будто уже знала, что он сейчас начнётся. Никакой концентрации, восемь часов пользы.','Иногда лучший контроль времени — просто ходить раньше остальных.','Не усиливается при использовании ячейки более высокого уровня.','Бонус применяется ко всем броскам инициативы цели, пока заклинание действует.',null),
('jim-s-magic-missile','Волшебная стрела Джима','Создаёшь три магических снаряда и для каждого отдельно совершаешь дальнобойную атаку заклинанием. При попадании снаряд наносит 2к4 урона силовым полем; критическое попадание наносит 5к4. Если на любой атаке выпадает натуральная 1, все снаряды промахиваются и взрываются у тебя в лицо, нанося тебе по 1 урону силовым полем за каждый снаряд.','Джим посмотрел на надёжную Волшебную стрелу и решил, что ей явно не хватает бросков атаки, критов, осечек и лицензионного сбора. Результат объективно веселее оригинала.','Когда улучшение продукта включает возможность взорвать самого покупателя — это уже бренд.','За каждый уровень ячейки выше 1 создаётся ещё один снаряд, а стоимость лицензионного компонента увеличивается на 1 зм.','Базовый материальный/лицензионный компонент стоит 1 зм и расходуется. Каждый снаряд требует отдельного броска атаки.',null),
('magnify-gravity','Усиление гравитации','Усиливаешь притяжение в сфере радиусом 10 футов в пределах дистанции. Существа в области совершают спасбросок Телосложения: при провале получают 2к8 урона силовым полем и их скорость уменьшается вдвое до конца следующего хода; при успехе получают половину урона без снижения скорости.','На несколько секунд пространство решает, что все внутри должны весить существенно больше. Отличный способ одновременно причинить боль и испортить планы на перемещение.','Гравитация обычно бесплатна. Эта версия просто берёт доплату за сервис.','Урон увеличивается на 1к8 за каждый уровень ячейки выше 1.','Снижение скорости действует только после проваленного спасброска и заканчивается в конце следующего хода цели.',null),
('silvery-barbs','Серебристые шипы','Реакцией после того, как видимое существо в пределах 60 футов успешно совершило атаку, проверку характеристики или спасбросок, заставляешь его перебросить к20 и использовать меньший результат. Затем выбираешь другое видимое существо в пределах дистанции, включая себя: оно получает преимущество на следующую атаку, проверку или спасбросок в течение 1 минуты.','Ты превращаешь чужой успех в «а брось-ка ещё раз» и одновременно выдаёшь кому-то другому купон на преимущество. Очень маленькое заклинание с очень неприятным социальным эффектом за столом.','Самое страшное слово после натуральной двадцатки: «реакция».','Не усиливается при использовании ячейки более высокого уровня.','Вторая выбранная цель должна отличаться от существа, которое ты заставил перебросить. Преимущество тратится на первый подходящий бросок.','1 реакция, когда видимое существо в пределах 60 футов успешно совершает атаку, проверку характеристики или спасбросок'),
('snare','Силок','За 1 минуту создаёшь скрытую магическую ловушку из 25 футов верёвки на земле. Когда подходящее существо входит в область, оно совершает спасбросок Ловкости; при провале его подвешивает вверх ногами примерно на 3 фута и оно становится Опутанным. Пойманная цель может пытаться освободиться в конце своих ходов.','Это охотничий силок, только магия делает всю грязную работу сама. Особенно хорош там, где противник уверен, что никто не станет тратить минуту на подготовку пола.','Волшебник тоже умеет ставить капканы. Просто его капкан читает спасброски.','Не усиливается при использовании ячейки более высокого уровня.','Верёвка расходуется при сотворении. Ловушку трудно заметить; освобождение возможно собственными попытками цели или помощью другого существа.',null),
('spellfire-flare','Вспышка магического огня','Совершишь дальнобойную атаку заклинанием по цели в пределах 60 футов. Половинное и трёхчетвертное укрытие не дают цели бонуса против этой атаки. При попадании цель получает 2к10 урона излучением.','Очень яркий прямой выстрел, которому особенно всё равно, насколько уверенно противник выглядывает из-за стены. Простое заклинание, но с отличным масштабированием.','Укрытие помогает от многих вещей. От магического огня — заметно меньше.','За каждый уровень ячейки выше 1 создаётся ещё одна вспышка. Для каждой совершается отдельная атака; вспышки можно направлять в одну или разные цели.','Каждая вспышка требует отдельного броска атаки. Половинное и трёхчетвертное укрытие не дают бонус к КД против этих атак.',null),
('tasha-s-caustic-brew','Едкое варево Таши','Выплёскиваешь кислоту линией длиной 30 футов и шириной 5 футов. Существа в линии совершают спасбросок Ловкости; при провале покрываются кислотой и в начале каждого своего хода получают 2к4 урона кислотой, пока заклинание действует. Существо может действием очистить кислоту с себя или другой цели.','Таша предлагает решить проблему не мгновенным взрывом, а липкой кислотой, которая продолжает напоминать о себе каждый ход, пока кто-нибудь не потратит действие на уборку.','Боевой контроль через обязательную санитарную обработку.','Урон в начале хода увеличивается на 2к4 за каждый уровень ячейки выше 1.','Требуется концентрация до 1 минуты. Успешный спасбросок при попадании в линию полностью избегает эффекта.',null),
('wardaway','Отгоняющий оберег','Одно существо в пределах 60 футов совершает спасбросок Телосложения; Конструкты и Нежить автоматически преуспевают. При провале цель получает 2к4 урона силовым полем, её скорость уменьшается вдвое до начала твоего следующего хода, а в свой следующий ход она может совершить либо действие, либо бонусное действие, но не оба. При успехе получает только половину урона.','Короткий магический удар, который не столько уничтожает цель, сколько заставляет её следующий ход пройти в режиме серьёзного торможения.','Иногда лучший контроль — заставить врага выбрать, какой половиной своего хода он сегодня пользуется.','Урон увеличивается на 2к4 за каждый уровень ячейки выше 1.','Конструкты и Нежить автоматически преуспевают в спасброске. При успешном спасброске дополнительные ограничения не применяются.',null),
('zephyr-strike','Удар Зефира','Пока поддерживаешь концентрацию до 1 минуты, твоё перемещение не провоцирует атаки. Один раз до окончания заклинания в свой ход можешь получить преимущество на одну атаку оружием; при попадании она наносит дополнительно 1к8 урона силовым полем. Независимо от попадания после этой атаки твоя скорость ходьбы увеличивается на 30 футов до конца хода.','На минуту ты начинаешь двигаться как ветер, а один выбранный удар превращается в особенно быстрый рывок с бонусным уроном. Отличный инструмент для мобильного следопыта.','Сначала ветер. Потом удар. Потом тебя уже нет на прежнем месте.','Не усиливается при использовании ячейки более высокого уровня.','Непровоцирование атак действует всё время концентрации. Преимущество, дополнительный урон и ускорение можно активировать только один раз за одно сотворение.',null)
) as v(slug,name_ru,effect_summary,author_description,author_comment,upcast,notes,casting_time)
where s.slug=v.slug and s.source_kind='official';

commit;
